source.exploreUrl:
@js:
const list = []
const push = (title, url, size) => list.push({
  title,
  url,
  style: {layout_flexBasisPercent: size||0.29}
});

const male = [{"title":"都市","value":"101"},{"title":"奇幻仙侠","value":"102"},{"title":"玄幻","value":"103"},{"title":"科幻末世","value":"104"},{"title":"悬疑灵异","value":"105"},{"title":"异能","value":"106"},{"title":"武侠","value":"107"},{"title":"历史","value":"108"},{"title":"游戏","value":"109"},{"title":"青春校园","value":"110"},{"title":"文学作品","value":"111"}]
const female = [{"title":"现代言情","value":"201"},{"title":"古代言情","value":"202"},{"title":"豪门总裁","value":"203"},{"title":"青春校园","value":"204"},{"title":"穿越","value":"205"},{"title":"重生","value":"206"},{"title":"婚恋情感","value":"207"},{"title":"文学作品","value":"208"},{"title":"其他","value":"209"}]

const st = {"all":"不限","0":"连载","1":"完结"}
let {status, toggle} = createConfig();

let url = `/api/novel/book/v2/class/book.do?parentClassId=$classId&classId=all&status=${status}&page={{page-1}}&size=10&vn=1.0.1.x&m=G8&t={{Date.now()}}&ch=xiaomi&pkg=com.smart.app.jiudianjiu.xin.leisureNovel`;

push("可从登录中选择状态","",1)
push("当前状态："+st[status],"",1)
push("男生", "", 1)
male.forEach({title, value} => 
	 push(title, url.replace("$classId", value))
)
push("女生", "", 1)
female.forEach({title, value} => 
	 push(title, url.replace("$classId", value))
)

var rankList = []
if(toggle.trim() === "✅"){
	 eval(String(source.variableComment))
}else{rankList = []}

JSON.stringify(list.concat(rankList))

