function login(){}

function show(){
	 const config = createConfig();
  const {status, toggle} = config;
  const st = {"all":"不限","0":"连载","1":"完结"}
  java.toast("\n当前状态：\n" + st[status] + "："+status+"\n排行榜："+toggle)
}

function setStatus(val){
	 const config = createConfig();
  config.status = String(val).trim();
  source.setVariable(JSON.stringify(config));
  source.refreshExplore()
}

function toggle(){
	 const config = createConfig();
  //let info = source.getLoginInfoMap();
  //let value = info["排行榜"]
  config.toggle = String(result.get("排行榜"));
  source.setVariable(JSON.stringify(config))
  source.refreshExplore()
}

ruleSearch.wordCount:
$.words@js:
function formatWordCount(wordCount) {
    if(!wordCount) return "";
    if (wordCount < 1e4) {
        return wordCount + "字";
    } else {
        return (wordCount / 1e4).toFixed(1) + "万字";
    }
}

formatWordCount(result)

source.variableComment:
//排行榜
rankList = []
const pushRank = (title, url, size) =>
  rankList.push({
    title,
    url,
    style: {layout_flexBasisPercent: size||0.29}
  });

const genders = [{"title":"男生","value":"1"},{"title":"女生","value":"2"}]
const tops = [{"title":"推荐","value":"01"},{"title":"完结榜","value":"02"},{"title":"热搜榜","value":"03"}]

const rankUrl = "/api/novel/book/v2/top/book.do?topId=$genderId$topId&page={{page-1}}&size=10&vn=1.0.1.x&m=G8&t={{Date.now}}&ch=xiaomi&pkg=com.smart.app.jiudianjiu.xin.leisureNovel";
pushRank("排行榜","",1)
genders.forEach(({title,value})=>{
  tops.forEach(top => {
    let {title:toptitle,value:topval} = top;
    let url = rankUrl.replace("$genderId", value).replace("$topId", topval)
    pushRank(title+toptitle, url)
  })
})

