source.loginUrl:
//打印字符串
function login(t){
		if(t==undefined)return true;
		java.toast(t);
		java.log(t);
	}
getv=()=>{
	try{
		$=JSON.parse(source.getVariable());
	}catch(err){$=null}
	return $
}
setv=(json)=>source.setVariable(JSON.stringify(json));
getd=()=>new Date().getTime();



//ajax
ajax=()=>{
		h = org.jsoup.Jsoup.parse(java.ajax(url));
if(String(h).length){
		return 1
	}
else{
		i++
		return i<3?ajax():0
	}
}



//获取urls
getu=(type)=>{
		$.type1 = type

if(type=='c'){
		if($.type3==null){
				t = '请先选择接口'
			}
		else{
				$.url = $.b.urls[$.type3];
				t = '更改接口成功'
				$.type1 = null
				$.type3 = null
			}
	}
else{

if(  $[type].time+6E8>getd() && $.type2==0  ){
		t = '离上次获取不超过7天，确定获取吗？'
	}
else if(  type=='b' && $.type3==null  ){
		t = '请先选择接口'
	}
else{
if(type=='b'){
var $chars = 'abcdefhijklmnopqrstuvwxyz123456789';
var maxPos = $chars.length;
var pwd = '';
for (i = 0; i < 15; i++) {
		pwd += $chars.charAt(Math.floor(Math.random() * maxPos));
	}
		url = String($.a.urls[$.type3]).replace(/\/?$/,'/'+pwd)
	}
else{
		url = source.getKey();
	}
i=0
if(ajax()){
		i = 0,
		u = Array.from(h.select('.line a'))
		.map(a=>{
				href = a.attr('href');
		if(  !/^\s*$/.test(href) && String($[type].urls).indexOf(href)==-1  ){
				$[type].urls.push(href);
				i++
			}
		});
		$[type].time=getd()
		$.type1=null
		$.type2=0;
		$.type3=null;
		t='获取成功，新增加'+i+'个接口'
	}
else{
		t='ajax失败'
	}
}}

login(t);
return setv($);
}



//选择序号
$$=(i)=>{
if($.type1=='a'||$.type1==null)return;

type = $.type1.replace('b','a').replace('c','b');

if($[type].urls[i]==$.url){
		t=`【无需选中】正在使用`
		i=null
	}
else if($[type].urls[i]==undefined){
		t=`【无法获取】请换一个`
		i=null
	}
else if(i==$.type3){
		t=`【取消选中】 取消选中`+(i+1)
		i=null
	}
else{
		t=`【成功选中】 成功选中`+(i+1)
	}
		login(t);
		$.type3=i;
		return setv($);
}



//是否确定
choice=(type)=>{
if($.type1==null)return;
		$.type2=type
if(type==1)return getu($.type1);
		$.type1=null
		$.type3=null
		login('已取消选择')
		return setv($);
	}


//分类样式储存
getc=(c)=>c==0?"类型":c==1?"排序":"状态";
setc=(i)=>{
		if($.c==i)return;
		t = '分类样式更改成功: '+getc($.c)+'=>'+getc(i)+'，请刷新发现';
		login(t);
		$.c = i;
		return setv($);
	}





//初始化
getv();
if(/^\s*$/.test($)||$==null){
$ = {
		url: '',//当前接口
		type1: '',//操作类别(获取/选择)
		type2: 1,//确定选择？(0/1)
		type3: 0,//当前选中接口序号
		a: {
				time: 0,//上次获取时间
				urls: []//发布列表
			},
		b: {
				time: 0,//上次获取时间
				urls: []//网址列表
			},
		c: 2//分类样式(0,1,2)
	};
setv($);
login('【初始化】正在获取发布')
getu('a')


getv();//默认获取接口0
$.type2=1
$.type3=0
java.log($.a.urls.join('\n[　 发布 　] '))


login('【初始化】注入默认发布\n[　 发布 　] https://zozozo.xyz/?\n[　 发布 　] https://kookookoo.xyz/?')
$.a.urls.push("https://zozozo.xyz/?","https://kookookoo.xyz/?")

login('【初始化】正在获取网站')
getu('b')

getv();//默认获取接口0
$.type2=1
$.type3=0
java.log($.b.urls.join('\n[　 网站 　] '))
login('【初始化】正在启用接口')
getu('c')
}

