                data.position = resetValue;
                if (data.index > length) return '';
                data.val = getNextValue(data.index++);
            }
            res |= (bit > 0 ? 1 : 0) * power;
            power <<= 1;
        }

        let next;
        switch (res) {
            case 0: // 8 位字符
                res = 0;
                maxPower = Math.pow(2, 8);
                power = 1;
                while (power != maxPower) {
                    let bit = data.val & data.position;
                    data.position >>= 1;
                    if (data.position == 0) {
                        data.position = resetValue;
                        if (data.index > length) return '';
                        data.val = getNextValue(data.index++);
                    }
                    res |= (bit > 0 ? 1 : 0) * power;
                    power <<= 1;
                }
                next = String.fromCharCode(res);
                break;
            case 1: // 16 位字符
                res = 0;
                maxPower = Math.pow(2, 16);
                power = 1;
                while (power != maxPower) {
                    let bit = data.val & data.position;
                    data.position >>= 1;
                    if (data.position == 0) {
                        data.position = resetValue;
                        if (data.index > length) return '';
                        data.val = getNextValue(data.index++);
                    }
                    res |= (bit > 0 ? 1 : 0) * power;
                    power <<= 1;
                }
                next = String.fromCharCode(res);
                break;
            case 2: // 结束
                return '';
