@js:
(function(){
  var json = JSON.parse(String(result));
  var chapters = (json && json.chapters) || [];
  var base = String(typeof baseUrl !== 'undefined' ? baseUrl : 'https://www.aaawz.cc').replace(/^(https?:\/\/[^\/]+).*$/, '$1');
  var map = null;
  if (json.font && json.font.url) {
    var fontUrl = String(json.font.url);
    if (fontUrl.indexOf('http') !== 0) fontUrl = base + fontUrl;
    var key = 'aaawz_map_' + fontUrl.split('/').pop();
    try { var cached = source.get(key); if (cached) map = JSON.parse(cached); } catch (e) {}
    if (!map) {
      var latin = String(java.ajax(fontUrl + ',{"charset":"ISO-8859-1"}'));
      if (latin && latin.length > 100) {
        map = aaawzBuildMapFromLatin(latin);
        if (map) { try { source.put(key, JSON.stringify(map)); } catch (e) {} }
      }
    }
  }
  var m = String(typeof baseUrl !== 'undefined' ? baseUrl : '').match(/api-chapterlist-(\d+)-(\d+)/);
  var tid = m ? m[1] : '', sid = m ? m[2] : '';
  return chapters.map(function (ch) {
    var title = String(ch.title || '');
    if (map) title = aaawzRestore(title, map);
    return {title: title, url: base + '/api-chapter-' + tid + '-' + sid + '-' + ch.cid + '?format=g2'};
  });
})()

