@js:
var result = [];
var push = (title, url, size) => result.push({
    title: java.t2s(title),
    url: url && /_/.test(url) ? `/novels/${url}.html` : url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: size
    }
});

push("书籍分类", null, 1);

const tag = org.jsoup.Jsoup.parse(Ajax(source.key + "/novels/hot")).select('.listleft li:not([class]) a');
const sort = [
    ["全部", "monthvisit_0_0_1"],
    ["连载", "newhot_0_0_1"],
    ["全本", "newhot_0_1_1"],
    ["人气", "weekvisit_0_0_1"],
    ["推荐", "allvote_0_0_1"],
    ["新书", "newhot_0_0_1"]
];

sort.forEach(([name, pattern]) => {
    let Url = pattern.replace(/1$/, "{{page}}");
    push(`༺ˇ»\`ʚ  ${name}  ɞ´«ˇ༻`, Url, 1);
    tag.toArray().forEach((e, i) => push(e.text(), Url.replace(/^(.+?_)0/, `$1${i+1}`), 0.25));
});

push("༺ˇ»`ʚ  标签  ɞ´«ˇ༻", null, 1);
org.jsoup.Jsoup.parse(Ajax(source.key + "/newtags")).select('.tag a').forEach(n => 
    push(n.text(), n.attr('href') + "{{page}}", -1)
);

JSON.stringify(result);

source.jsLib:
var Regex = /Just a moment|onloadTurnstileCallback/;
function Ajax(url) {
     const { java } = this;
     let result = java.ajax(url);
     let retryCount = 0;
     const maxRetries = 3;
     while (Regex.test(result) && retryCount < maxRetries) {
      result = java.startBrowserAwait(url, "验证").body();
     }
     return result;
}

